import {
  type FieldViewProps,
  useField,
  useFieldError,
  useFieldOptions
} from 'alinea/cms'
import {Select, SelectItem} from 'alinea/components'
import type {Priority, PriorityField} from './Priority'

export function PriorityView({field}: FieldViewProps<PriorityField>) {
  const [value, setValue] = useField(field)
  const options = useFieldOptions(field)
  const error = useFieldError(field)
  return (
    <Select
      label={options.label}
      value={value}
      onValueChange={next => setValue((next ?? 'normal') as Priority)}
      error={error}
      required={options.required}
      readOnly={options.readOnly}
      shared={options.shared}
    >
      <SelectItem value="low">Low</SelectItem>
      <SelectItem value="normal">Normal</SelectItem>
      <SelectItem value="high">High</SelectItem>
    </Select>
  )
}

import {Field} from 'alinea'

export type Priority = 'low' | 'normal' | 'high'
export type PriorityField = Field.Create<Priority>

export function priority(
  label: string,
  options: Field.Options<PriorityField> = {}
): PriorityField {
  return Field.create({
    label,
    options,
    defaultValue: (): Priority => 'normal',
    view: '@/fields/Priority.view#PriorityView'
  })
}

import {
  type FieldViewProps,
  useField,
  useFieldOptions,
  useFieldValue
} from 'alinea/cms'
import {TextField} from 'alinea/components'
import {BlogPost} from '@/schema'
import type {CaptionField} from './Caption'

export function CaptionView({field}: FieldViewProps<CaptionField>) {
  const [value, setValue] = useField(field)
  const {label} = useFieldOptions(field)
  // A field of the entry, read from inside a list row
  const title = useFieldValue(BlogPost.title)
  return (
    <TextField
      label={label}
      value={value}
      placeholder={title}
      onValueChange={setValue}
    />
  )
}

import {Config, Field} from 'alinea'

export const Product = Config.document('Product', {
  fields: {
    title: Field.text('Title'),
    ...Field.view('@/fields/ProductUrls.view#ProductUrls')
  }
})

import {useEntry} from 'alinea/cms'
import {Field, Link} from 'alinea/components'

export function ProductUrls() {
  const entry = useEntry()
  if (!entry) return null
  return (
    <Field label="Public URL" description="Where this product is published">
      <Link href={entry.url} target="_blank">
        {entry.url}
      </Link>
    </Field>
  )
}

import {Config, Field} from 'alinea'

export const Product = Config.document('Product', {
  view: '@/views/ProductView.view#ProductView',
  fields: {
    summary: Field.text('Summary', {multiline: true}),
    price: Field.number('Price')
  }
})

import {EditField, useField} from 'alinea/cms'
import {TextField} from 'alinea/components'
import {Product} from '@/schema/Product'

export function ProductView() {
  const [summary = '', setSummary] = useField(Product.summary)
  return (
    <div style={{display: 'grid', gap: 16, padding: 24}}>
      <TextField
        label="Summary"
        multiline
        value={summary}
        onValueChange={setSummary}
      />
      <EditField field={Product.price} />
    </div>
  )
}

import {Config, Field} from 'alinea'

export const Product = Config.document('Product', {
  fields: {title: Field.text('Title')},
  actions: ['@/views/ExportProduct.view#ExportProduct']
})

import {type EntryActionProps, useFieldValue} from 'alinea/cms'
import {Button} from 'alinea/components'
import {Product} from '@/schema/Product'

export function ExportProduct({entry}: EntryActionProps) {
  const title = useFieldValue(Product.title)
  return (
    <Button onClick={() => window.open(`/api/export/${entry.id}`)}>
      Export {title}
    </Button>
  )
}
